      SUBROUTINE TWIT2CCC     DETERMINES CONTRIBUTION OF SECOND-ORDER TRANSFER MATRIX TOC     TRANSFORM OF PARTIALS OF BEAM CENTROIDCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'ELM7D.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'T.CIN'CC     LOCAL VARIABLESCCC     SECOND ORDER TERMSC      DO 20 J = 1, 5      IND = 0      SS = COT(J)      DO 10 L2 = 1, 6      DO 10 L1 = 1, L2      IND = IND + 1      SS = SS + T(J,IND)*(CO(L1)*COV(L2,NV2)      1                  + COV(L1,NV2)*CO(L2))   10 CONTINUE      COT(J) = SS   20 CONTINUEC      RETURN      END